source("pre.R"); suppressPackageStartupMessages(library(bit64))
x <- int64(c(1,2,3,2)); 
show("hashcache", {hashcache(x); names(attributes(x))}); show("cache", ls(attr(x, "cache")))
y <- x; y[1] <- 9L
show("attrs after [<-", names(attributes(y)))
show("match(9, y) [bit64 masked]", match(int64(9), y)); show("9 %in% y", int64(9) %in% y); show("match(1, y) want NA", match(int64(1), y)); show("unique(y)", unique(y)); show("duplicated", duplicated(y)); show("table", table(y))
show("as_integer64(y) attrs", names(attributes(as_integer64(y)))); show("match in as_integer64(y) want NA", match(as.integer64(1), as_integer64(y)))
z <- int64(c(3,1,2)); sortcache(z); show("sortcache attrs", names(attributes(z))); z2 <- z; z2[[2]] <- 100L; show("attrs", names(attributes(z2)))
show("sort(z2) [zuint]", sort(z2)); show("order(z2) [bit64 masked]", order(z2)); show("rank(z2)", rank(z2)); show("max via bit64?", max(z2)); show("quantile-ish qtile", tryCatch(qtile(z2, 0.5), error=function(e) conditionMessage(e)))
show("z + 1L attrs", names(attributes(z + 1L))); show("c(z, z) attrs", names(attributes(c(z, z)))); show("rev attrs", names(attributes(rev(z)))); show("z[1:2] attrs", names(attributes(z[1:2]))); show("order(rev(z))", order(rev(z)))
show("rev(z) order want 1 3 2? vals", format(rev(z)))
w <- z; length(w) <- 5; show("length<- attrs", names(attributes(w))); show("order(w)", order(w))
w <- z; names(w) <- c("a","b","c"); w2 <- sort(w); show("sort attrs", names(attributes(w2)))
w <- z; is.na(w) <- 1; show("is.na<- attrs", names(attributes(w))); show("order after is.na<-", order(w)); show("match(3, w) want NA", match(int64(3), w))
w <- z; w[5] <- 7L; show("grow attrs", names(attributes(w)))
w <- vctrs::vec_slice(z, 3:1); show("vec_slice attrs", names(attributes(w))); show("order", order(w))
w <- vctrs::vec_c(z, z); show("vec_c attrs", names(attributes(w)))
w <- uint64(z); show("uint64(z) attrs", names(attributes(w))); w <- int128(z); show("int128(z) attrs", names(attributes(w)))
w <- int64(as_integer64(z)); show("int64(integer64 w/ cache) attrs", names(attributes(w)))
b <- as.integer64(c(3,1,2)); sortcache(b); w <- int64(b); show("int64(cached integer64) attrs", names(attributes(w))); w[1] <- 0L; show("after [<-", names(attributes(w))); show("order(w) want 1 2 3", order(w)); show("match(3,w) want NA", match(int64(3), w))
